// Exercise the actual client components and API with controlled auth/storage.
// Run: node --test tests/account-conversation.test.cjs
const { test } = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const ts = require('typescript');
const root = path.join(__dirname, '..');
const history = [{ role: 'user', text: 'hello' }, { role: 'misaki', text: 'hi' }];
const ownerKey = 'misaki-device-user-id';
const pendingKey = 'misaki-email-save-user-id';
function storage(initial = {}) {
  const map = new Map(Object.entries(initial));
  return { get length() { return map.size; }, key: i => [...map.keys()][i] ?? null,
    getItem: k => map.get(k) ?? null, setItem: (k, v) => map.set(k, String(v)), removeItem: k => map.delete(k) };
}
async function flush() { for (let i = 0; i < 12; i++) await new Promise(setImmediate); }
function harness(user = { id: 'a', is_anonymous: true }, initial = {}, sessionInitial = {}) {
  const localStorage = storage({ [ownerKey]: 'a', 'misaki-chat-history': JSON.stringify(history),
    'misaki-long-term-memory': '["remember"]', 'misaki-auth-kind': 'anonymous', ...initial });
  const sessionStorage = storage(sessionInitial);
  const states = [], effects = [], cleanups = [], calls = [], listeners = [];
  let cursor = 0, mounted = false, currentUser = user;
  const react = { useState: value => {
    const i = cursor++;
    if (!(i in states)) states[i] = value;
    return [states[i], next => { states[i] = typeof next === 'function' ? next(states[i]) : next; }];
  }, useEffect: fn => { if (!mounted) effects.push(fn); }, useLayoutEffect: fn => { if (!mounted) effects.push(fn); } };
  const client = { auth: {
    getSession: async () => ({ data: { session: currentUser ? { user: currentUser, access_token: 'token' } : null }, error: null }),
    getUser: async () => ({ data: { user: currentUser }, error: null }),
    signOut: async () => { calls.push('signOut'); currentUser = null; return { error: null }; },
    signInAnonymously: async () => { calls.push('signIn'); currentUser = { id: 'new', is_anonymous: true }; return { data: { user: currentUser }, error: null }; },
    updateUser: async () => { calls.push('email'); return { error: null }; },
    onAuthStateChange: fn => { listeners.push(fn); return { data: { subscription: { unsubscribe() {} } } }; },
  }, rpc: async (name, args) => { calls.push({ name, args }); return { data: { saved: true }, error: null }; } };
  const context = vm.createContext({ localStorage, sessionStorage, Response, Request, Date, JSON, navigator: {}, crypto: require("node:crypto").webcrypto, AbortSignal,
    CustomEvent: class { constructor(type, init) { this.type = type; this.detail = init?.detail; } },
    console: { error() {} }, fetch: (...args) => h.fetch(...args),
    window: { location: { origin: 'https://example.test', reload: () => calls.push('reload') },
      setInterval() {}, clearInterval() {}, setTimeout: fn => fn(), addEventListener() {}, removeEventListener() {}, dispatchEvent() {} },
    document: { visibilityState: 'visible', addEventListener() {}, removeEventListener() {} } });
  const cache = new Map();
  function load(file) {
    if (cache.has(file)) return cache.get(file);
    const output = ts.transpileModule(fs.readFileSync(path.join(root, file), 'utf8'), {
      compilerOptions: { module: ts.ModuleKind.CommonJS, jsx: ts.JsxEmit.ReactJSX, target: ts.ScriptTarget.ES2020 }
    }).outputText;
    const module = { exports: {} };
    const req = name => {
      if (name === 'react') return react;
      if (name === 'react/jsx-runtime') return { jsx: (type, props) => ({ type, props }), jsxs: (type, props) => ({ type, props }), Fragment: 'fragment' };
      if (name === '@supabase/supabase-js') return { createClient: () => client };
      if (name.endsWith('/push-notifications')) return { registerPushSubscription: async () => {}, sendTestPushNotification: async () => {} };
      if (name.endsWith('/maintenance-result')) return load('lib/maintenance-result.ts');
      if (name.endsWith('/maintenance')) return { maintenanceResponse: async () => null };
      if (name.endsWith('/supabase')) return { supabase: client };
      if (name.endsWith('/canonical-state')) return {
        createServerSupabase: () => client,
        forgetControlPayload: async () => 'encrypted-forget-control-fixture',
        openTemporaryState: token => token === 'verified' ? { state: { memory: ['remember'], memoryTimes: [['remember', Date.now() - 1000]], history: history.map(item => ({ ...item, sentAt: new Date(Date.now() - 1000).toISOString() })), todayMemory: { date: '', items: [] }, relationshipPoints: 2 } } : null,
        loadTemporaryRoot: async (_id, token) => token === 'verified' ? { memory: ['remember'], memoryTimes: [['remember', Date.now() - 1000]], history: history.map(item => ({ ...item, sentAt: new Date(Date.now() - 1000).toISOString() })), todayMemory: { date: '', items: [] }, relationshipPoints: 2 }
          : { memory: [], history: [], todayMemory: { date: '', items: [] }, relationshipPoints: 0 },
        sealTemporaryState: () => 'verified',
      };
      if (name.endsWith('/temporary-state-error')) return load('lib/temporary-state-error.ts');
      if (name.endsWith('/recovery-session')) return load('lib/recovery-session.ts');
      if (name.endsWith('/_shared/forget-control')) return {};
      if (name.endsWith('/_shared/anonymous-memory-expiry')) return load('supabase/functions/_shared/anonymous-memory-expiry.ts');
      if (name === './anonymous-history-expiry.ts') return load('supabase/functions/_shared/anonymous-history-expiry.ts');
      if (name.endsWith('/device-conversation')) return load('lib/device-conversation.ts');
      throw Error(name);
    };
    vm.runInContext(`(function(require,module,exports){${output}\n})`, context)(req, module, module.exports);
    cache.set(file, module.exports);
    return module.exports;
  }
  const h = { window: context.window, localStorage, sessionStorage, states, calls, client, load,
    fetch: async () => Response.json({ exists: true, history, memory: ['remember'] }),
    setUser: u => { currentUser = u; }, emit: (event, u) => listeners.forEach(fn => fn(event, u ? { user: u } : null)),
    render(file, props = {}) { cursor = 0; const tree = load(file).default(props); mounted = true; return tree; },
    async mount(file, props) { const tree = this.render(file, props); effects.splice(0).forEach(fn => { const cleanup = fn(); if (cleanup) cleanups.push(cleanup); }); await flush(); return tree; },
    unmount() { cleanups.forEach(fn => fn()); } };
  return h;
}
function find(tree, text) {
  if (!tree || typeof tree !== 'object') return null;
  if (tree.type === 'button' && tree.props.children === text) return tree;
  for (const child of [tree.props?.children].flat(Infinity)) { const match = find(child, text); if (match) return match; }
  return null;
}
test('email save checkpoints authenticated temporary state before updateUser', async () => {
  const h = harness(undefined, {}, { 'misaki-temporary-state-v1': 'verified' });
  h.fetch = async (_url, options) => { h.calls.push('save');
    const body = JSON.parse(options.body);
    assert.equal(body.expectedUserId, 'a'); assert.equal(body.saveAnonymous, true);
    assert.equal(body.temporaryState, 'verified'); assert.equal(body.history, undefined); assert.equal(body.memory, undefined);
    return Response.json({ synced: true }); };
  await h.mount('app/account/page.tsx'); h.states[2] = 'test@example.test';
  await find(h.render('app/account/page.tsx'), 'メールで保存する').props.onClick();
  assert.deepEqual(h.calls, ['save', 'email']); assert.equal(h.localStorage.getItem(pendingKey), 'a');
});

test('maintenance checkpoint response keeps email unsent and displays maintenance', async () => {
  const h = harness(undefined, {}, { 'misaki-temporary-state-v1': 'verified' });
  h.fetch = async () => Response.json({ maintenance: true, code: 'MAINTENANCE', error: 'メンテナンス中です。' }, { status: 503 });
  await h.mount('app/account/page.tsx'); h.states[2] = 'test@example.test';
  await find(h.render('app/account/page.tsx'), 'メールで保存する').props.onClick();
  assert.ok(!h.calls.includes('email')); assert.equal(h.localStorage.getItem(pendingKey), null);
  assert.ok(h.states.includes('メンテナンス中です。'));
});

for (const failedEmail of [true, false]) test(`${failedEmail ? 'failed email send' : 'pending confirmation'}: saveByEmail retry preserves additional server conversation`, async () => {
  const server = require('./helpers/canonical-harness.cjs').harness({ anonymous: true });
  const chat = server.load('app/api/chat/route.ts'), api = server.load('app/api/persona/history/route.ts');
  const first = await (await chat.POST(server.request())).json();
  const h = harness(server.user, { [ownerKey]: server.user.id }, { 'misaki-temporary-state-v1': first.temporaryState });
  let emails = 0;
  h.client.auth.updateUser = async () => ({ error: ++emails === 1 && failedEmail ? new Error('email transport failed') : null });
  h.fetch = async (_url, options) => api.POST(new Request('https://test/api/persona/history', options));
  await h.mount('app/account/page.tsx'); h.states[2] = 'test@example.test';
  await find(h.render('app/account/page.tsx'), 'メールで保存する').props.onClick();
  assert.equal(emails, 1);
  const additional = await chat.POST(server.request({ message: '保存再試行前の追加会話',
    requestId: require('node:crypto').randomUUID(), temporaryState: first.temporaryState }));
  assert.equal(additional.status, 200);
  // Simulate a tab with an old display token. The server root still wins.
  await find(h.render('app/account/page.tsx'), 'メールで保存する').props.onClick();
  assert.equal(emails, 2); server.user.is_anonymous = false;
  const state = await server.load('lib/canonical-state.ts').loadCanonicalState(server.user.id);
  assert.equal(state.relationshipPoints, 0);
  assert.ok(state.history.some(item => item.text === '保存再試行前の追加会話'));
});
test('failed checkpoint never sends confirmation email', async () => {
  const h = harness(); h.fetch = async () => new Response('', { status: 500 });
  await h.mount('app/account/page.tsx'); h.states[2] = 'test@example.test';
  await find(h.render('app/account/page.tsx'), 'メールで保存する').props.onClick();
  assert.ok(!h.calls.includes('email')); assert.equal(h.localStorage.getItem(pendingKey), null);
});
